#include<bits/stdc++.h>
#include<math.h>
#define rep(i,k,n) for(int i=k;i<n;i++)
#define ll long long
#define MOD1 998244353ll
#define MOD2 1000000009ll
#define MOD3 1000000007ll
#define MIN(a,b) (a>b?b:a)
using namespace std;
#define mp make_pair
#define pb push_back
#define piii pair<pair<ll,ll>,ll>
#define pii pair<ll,ll>
#define fi first
#define se second
#define debug(...) fprintf(stderr, __VA_ARGS__), fflush(stderr)
#define time__(d) \
    for ( \
        auto blockTime = make_pair(chrono::high_resolution_clock::now(), true); \
        blockTime.second; \
        debug("%s: %lld ms\n", d, chrono::duration_cast<chrono::milliseconds>(chrono::high_resolution_clock::now() - blockTime.first).count()), blockTime.second = false \
    )
#define MAXN 100005
const ll INF = 1000*1000*1000;

struct edge {
    ll to, cap, cost, flow;
    size_t rev;
};

void add_edge(vector<vector<edge>>& g, ll a, ll b, ll u, ll c) {
    edge e1 = {b, u, c, 0, g[b].size()};
    edge e2 = {a, 0, -c, 0, g[a].size()};
    g[a].push_back(e1);
    g[b].push_back(e2);
}

namespace k{
    ll n,m,k,c,d;
}
vector <ll> vr[55];
ll lr[50];
int main()
{
    ll n=50*99+1, m, k=INF;
    vector<vector<edge>> g(n);
    ll s, t;

    cin>>k::n>>k::m>>k::k>>k::c>>k::d;

    ll tim=99;
    for(int i=1;i<=k::k;++i)
    {
        cin>>lr[i];
        add_edge(g,0,lr[i],1,0);
    }
    for(int j=0;j<tim-1;++j)
    {
        for(int i=2;i<=k::n;++i)
            add_edge(g,j*50+i,(j+1)*50+i,50,k::c);
    }
    for(int j=1;j<tim;++j)
    {
        add_edge(g,j*50+1,1,50,0);
    }
    for(int i=0;i<k::m;++i)
    {
        ll x,y;
        cin>>x>>y;
        vr[x].push_back(y);
        vr[y].push_back(x);

        for(int j=0;j<tim-1;++j)
        {
            for(int l=0;l<50;++l)
            {
                add_edge(g,j*50+x,(j+1)*50+y,1,(k::c)+(k::d)*((l+1)*(l+1)-(l*l)));
                add_edge(g,j*50+y,(j+1)*50+x,1,(k::c)+(k::d)*((l+1)*(l+1)-(l*l)));
            }
        }
    }
    s=0,t=1;

    ll flow = 0, cost = 0;
    while (flow < k) {
        vector<ll> dist(n, INF);
        vector<ll> prevv(n, -1);
        vector<size_t> preve(n);
        vector<ll> q(n);
        vector<ll> inq(n, 0);
        ll qh=0, qt=0;
        q[qt++] = s;
        dist[s] = 0;
        inq[s] = 1;
        while (qh != qt) {
            ll v = q[qh++];
            inq[v] = 0;
            if (qh == n) qh = 0;
            for (size_t i=0; i<g[v].size(); ++i) {
                edge &e = g[v][i];
                if (e.flow < e.cap && dist[v] + e.cost < dist[e.to]) {
                    dist[e.to] = dist[v] + e.cost;
                    prevv[e.to] = v;
                    preve[e.to] = i;
                    if (!inq[e.to]) {
                        q[qt++] = e.to;
                        if (qt == n) qt = 0;
                        inq[e.to] = 1;
                    }
                }
            }
        }
        if (dist[t] == INF) break;
        ll add = k - flow;
        for (ll v=t; v!=s; v=prevv[v]) {
            ll pv = prevv[v]; size_t pe = preve[v];
            add = min(add, g[pv][pe].cap - g[pv][pe].flow);
        }
        for (ll v=t; v!=s; v=prevv[v]) {
            ll pv = prevv[v]; size_t pe = preve[v];
            size_t re = g[pv][pe].rev;
            g[pv][pe].flow += add;
            g[v][re].flow -= add;
            cost += g[pv][pe].cost * add;
        }
        flow += add;
    }
    cout<<cost<<"\n";
}
